{
    local current previous cmd
    COMPREPLY=()
    current="${COMP_WORDS[COMP_CWORD]}"
    previous="${COMP_WORDS[COMP_CWORD - 1]}"
    # The subcommand is always the second token (index 1).
    cmd="${COMP_WORDS[1]}"
    # Step 1: resolve single-character shortcuts to their canonical command name
    # so that subsequent case statements only need to handle canonical names.
    case "$cmd" in
        i) cmd=init ;;
        a) cmd=add ;;
        y) cmd=bind ;;
        m) cmd=import ;;
        c) cmd=compile ;;
        p) cmd=parse ;;
        s) cmd=serve ;;
        w) cmd=watch ;;
        e) cmd=env ;;
        b) cmd=build ;;
        d) cmd=deploy ;;
        l) cmd=login ;;
        o) cmd=logout ;;
        t) cmd=test ;;
        v) cmd=version ;;
        h) cmd=help ;;
        r) cmd=repl ;;
    esac

    # Step 2: top-level — offer all known subcommands when no subcommand has been
    # typed yet (COMP_WORDS includes the command itself, so ≤ 2 means "cds <cursor>").
    if [[ "${#COMP_WORDS[@]}" -le 2 ]]; then
        COMPREPLY=( $(compgen -W ""add" "bind" "build" "compile" "completion" "debug" "deploy" "env" "eval" "export" "gen" "help" "import" "init" "inspect" "lint" "login" "logout" "minify" "mock" "parse" "pull" "push" "repl" "run" "serve" "subscribe" "test" "unsubscribe" "up" "upgrade" "upgrade-tenant" "version" "watch"" -- "$current") )
