            case "$previous" in
            --to) COMPREPLY=( $(compgen -W ""json" "yml" "edm" "edmx" "edmx-v2" "edmx-v4" "sql" "hdbtable" "hana" "cdl" "xsuaa" "openapi" "asyncapi"" -- "$current") ) ; return 0 ;;
            --for) COMPREPLY=( $(compgen -W ""odata" "sql"" -- "$current") ) ; return 0 ;;
            --dialect) COMPREPLY=( $(compgen -W ""sqlite" "h2" "postgres" "hana"" -- "$current") ) ; return 0 ;;
            --sql-dialect) COMPREPLY=( $(compgen -W ""sqlite" "h2" "postgres" "hana"" -- "$current") ) ; return 0 ;;
            --log-level) COMPREPLY=( $(compgen -W ""debug" "info" "warn" "error"" -- "$current") ) ; return 0 ;;
            --odata-version) COMPREPLY=( $(compgen -W ""4.0" "4.01"" -- "$current") ) ; return 0 ;;
            --flavor) COMPREPLY=( $(compgen -W ""sources" "files" "parsed" "xtended" "inferred"" -- "$current") ) ; return 0 ;;
            --service) COMPREPLY=( $(compgen -W ""all"" -- "$current") ) ; return 0 ;;
            --lang) COMPREPLY=( $(compgen -W ""all"" -- "$current") ) ; return 0 ;;
            --dest) COMPREPLY=( $(compgen -d -- "$current") ) ; return 0 ;;
            esac ;;
        up)
            case "$previous" in
            --to) COMPREPLY=( $(compgen -W ""cf" "k8s"" -- "$current") ) ; return 0 ;;
            esac ;;
        version)
            case "$previous" in
            --omit) COMPREPLY=( $(compgen -W ""dev" "optional" "peer"" -- "$current") ) ; return 0 ;;
            esac ;;
        watch)
            case "$previous" in
            --experimental-hot-reload) COMPREPLY=( $(compgen -W ""true" "false"" -- "$current") ) ; return 0 ;;
            --livereload) COMPREPLY=( $(compgen -W ""false"" -- "$current") ) ; return 0 ;;
            --include) COMPREPLY=( $(compgen -d -- "$current") ) ; return 0 ;;
            --exclude) COMPREPLY=( $(compgen -d -- "$current") ) ; return 0 ;;
            esac ;;

    esac

    # Step 3.6: comma-separated option-value completion.
    # Splits $current on commas, filters out already-used values, prepends the prefix.
    case "$cmd" in
        add)
            case "$previous" in
            *)
                [[ "$previous" == -* ]] && return 0
                local prefix="" partial="" IFS=,
                if [[ "$current" == *,* ]]; then
                    prefix="${current%,*},"
                    partial="${current##*,}"
                else
                    partial="$current"
                fi
                local -a _used
                read -ra _used <<< "${prefix%,}"
                local _all=("ai" "ams" "app-frontend" "application-logging" "approuter" "attachments" "audit-logging" "cf-manifest" "cjs" "cloud-logging" "completion" "connectivity" "console" "data" "destination" "dynatrace" "enterprise-messaging" "enterprise-messaging-shared" "event-mesh" "event-mesh-shared" "extensibility" "extension" "file-based-messaging" "github-actions" "h2" "hana" "hana-serverless" "handler" "html5-repo" "http" "ias" "initial" "kafka" "kyma" "lint" "liquibase" "local-messaging" "malware-scanner" "mta" "mtx" "multitenancy" "notifications" "pipeline" "portal" "postgres" "react" "redis" "redis-messaging" "sample" "side-by-side-extensibility" "sqlite" "telemetry" "test" "tiny-sample" "toggles" "typer" "typescript" "ui5" "vue" "workzone" "workzone-standard" "xsuaa")
                for v in "${_all[@]}"; do
                    [[ " ${_used[*]} " == *" $v "* ]] && continue
                    [[ "$v" == "$partial"* ]] && COMPREPLY+=("$prefix$v")
                done
                [[ ${#COMPREPLY[@]} -gt 0 ]] && { compopt -o nospace; return 0; } ;;
            esac ;;
        init)
            case "$previous" in
            --add)
                local prefix="" partial="" IFS=,
                if [[ "$current" == *,* ]]; then
                    prefix="${current%,*},"
                    partial="${current##*,}"
                else
                    partial="$current"
                fi
                local -a _used
                read -ra _used <<< "${prefix%,}"
                local _all=("ai" "ams" "app-frontend" "application-logging" "approuter" "attachments" "audit-logging" "cf-manifest" "cjs" "cloud-logging" "completion" "connectivity" "console" "data" "destination" "dynatrace" "enterprise-messaging" "enterprise-messaging-shared" "event-mesh" "event-mesh-shared" "extensibility" "extension" "file-based-messaging" "github-actions" "h2" "hana" "hana-serverless" "handler" "html5-repo" "http" "ias" "initial" "kafka" "kyma" "lint" "liquibase" "local-messaging" "malware-scanner" "mta" "mtx" "multitenancy" "notifications" "pipeline" "portal" "postgres" "react" "redis" "redis-messaging" "sample" "side-by-side-extensibility" "sqlite" "telemetry" "test" "tiny-sample" "toggles" "typer" "typescript" "ui5" "vue" "workzone" "workzone-standard" "xsuaa")
                for v in "${_all[@]}"; do
                    [[ " ${_used[*]} " == *" $v "* ]] && continue
                    [[ "$v" == "$partial"* ]] && COMPREPLY+=("$prefix$v")
                done
                [[ ${#COMPREPLY[@]} -gt 0 ]] && { compopt -o nospace; return 0; } ;;
            esac ;;

    esac

    # Step 4: file-sentinel positionals — fill COMPREPLY with files and return.
    case "$cmd" in
            compile) COMPREPLY=( $(compgen -f -- "$current" | grep -E '\.(cds|json)$') ) ;;
            deploy) COMPREPLY=( $(compgen -f -- "$current" | grep -E '\.(cds|json)$') ) ;;
            import) COMPREPLY=( $(compgen -f -- "$current" | grep -E '\.(json|xml|edmx)$') ) ;;
            inspect) COMPREPLY=( $(compgen -f -- "$current" | grep -E '\.(cds|json)$') ) ;;
            parse) COMPREPLY=( $(compgen -f -- "$current" | grep -E '\.(cds|json)$') ) ;;
    esac
    if [[ "${#COMPREPLY[@]}" -gt 0 ]]; then
        compopt -o nospace
        return 0
    fi

    # Step 4.6: string positionals (e.g. cds help <tab>).
    case "$cmd" in
            help) COMPREPLY=( $(compgen -W ""add" "bind" "build" "compile" "completion" "debug" "deploy" "env" "eval" "export" "gen" "help" "import" "init" "inspect" "lint" "login" "logout" "minify" "mock" "parse" "pull" "push" "repl" "run" "serve" "subscribe" "test" "unsubscribe" "up" "upgrade" "upgrade-tenant" "version" "watch"" -- "$current") ) ;;
    esac
    if [[ "${#COMPREPLY[@]}" -gt 0 ]]; then
        compopt -o nospace
        return 0
    fi

    # Step 5: dynamic fallback — calls 'cds completion' for subcommands whose arguments
    # cannot be determined statically (e.g. service names, model names, unknown flags).
    # Single-quoting $previous/$current prevents bare word 'h' from being interpreted
    # as the 'help' shortcut by the completion handler before it is processed.
    local options
    options=$($CDS_COMMAND completion --shell bash --prev "'$previous'" --curr "'$current'" --line "'${COMP_WORDS[*]}'")
    COMPREPLY=( $(compgen -W "${options}" -- "${current}") )
    compopt -o nospace
    return 0
}

# Register the completion function for the 'cds' command.
complete -F _completeCds "$CDS_COMMAND"
